"use strict";(globalThis.webpackChunkmy_website=globalThis.webpackChunkmy_website||[]).push([[477],{3643(e,n,i){i.r(n),i.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>p,frontMatter:()=>s,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"policies","title":"II. EMPLOYMENT POLICIES","description":"EQUAL EMPLOYMENT OPPORTUNITY POLICY","source":"@site/docs/02-policies.md","sourceDirName":".","slug":"/policies","permalink":"/pps-erp-sdd/policies","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/02-policies.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{},"sidebar":"tutorialSidebar","previous":{"title":"I. INTRODUCTION","permalink":"/pps-erp-sdd/"},"next":{"title":"III. COMPENSATION POLICY","permalink":"/pps-erp-sdd/compensation"}}');var t=i(4848),a=i(8453);const s={},r="II. EMPLOYMENT POLICIES",l={},c=[{value:"EQUAL EMPLOYMENT OPPORTUNITY POLICY",id:"equal-employment-opportunity-policy",level:2},{value:"PERSONNEL FILES",id:"personnel-files",level:2},{value:"ANTI-HARASSMENT POLICY",id:"anti-harassment-policy",level:2},{value:"Complaint Procedure",id:"complaint-procedure",level:3},{value:"Confidentiality",id:"confidentiality",level:3},{value:"Investigative Procedure",id:"investigative-procedure",level:3},{value:"Duties of Employees and Supervisors",id:"duties-of-employees-and-supervisors",level:3}];function d(e){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"ii-employment-policies",children:"II. EMPLOYMENT POLICIES"})}),"\n",(0,t.jsx)(n.h2,{id:"equal-employment-opportunity-policy",children:"EQUAL EMPLOYMENT OPPORTUNITY POLICY"}),"\n",(0,t.jsx)(n.p,{children:"The Company provides equal employment opportunities to all employees and applicants  without regard to race, color, religion, sex, sexual orientation, national origin, age,  disability, military status, or status as a Vietnam-era or special disabled veteran in  accordance with applicable federal and state laws."}),"\n",(0,t.jsx)(n.p,{children:"In addition, the Company complies  with applicable state and local laws governing nondiscrimination in employment in every  location in which the Company has facilities. This policy applies to all terms and  conditions of employment, including, but not limited to, hiring, placement, promotion,  termination, layoff, recall, transfer, leaves of absence, compensation and training."}),"\n",(0,t.jsx)(n.h2,{id:"personnel-files",children:"PERSONNEL FILES"}),"\n",(0,t.jsx)(n.p,{children:"Pressure Profile Systems, Inc. maintains a personnel file on each employee. You may  review your personnel file upon request and in the presence of authorized personnel. If  you are interested in reviewing your file, contact your Payroll Specialist to make  arrangements."}),"\n",(0,t.jsx)(n.p,{children:"To ensure that your personnel file is up-to-date at all times, notify your supervisor or your  Payroll Specialist of any changes in your name, telephone number, home address, marital  status, number of dependents, beneficiary designations, scholastic achievements, the  individuals to notify in case of an emergency, and so forth. An Employee Change in  Status Notice will need to be filled out and sent to Pressure Profile Systems, Inc."}),"\n",(0,t.jsx)(n.h2,{id:"anti-harassment-policy",children:"ANTI-HARASSMENT POLICY"}),"\n",(0,t.jsx)(n.p,{children:"It is the policy of the Company to maintain a working environment which encourages  mutual respect, promotes respectful and congenial relationships between employees and  is free from all forms of harassment of any employee or applicant for employment by  anyone, including supervisors, co-workers, vendors, or customers."}),"\n",(0,t.jsx)(n.p,{children:"Harassment in any  manner or form is expressly prohibited and will not be tolerated by the Company.  Accordingly, Company management is committed to vigorously enforcing this policy  against harassment, including but not limited to sexual harassment, at all levels within the  Company."}),"\n",(0,t.jsx)(n.p,{children:"All reported or suspected occurrences of harassment will be promptly and thoroughly  investigated. Where harassment is determined to have occurred, the Company will  immediately take appropriate disciplinary action, including written warnings and possible  suspension, transfer and/or termination. The Company will not permit or condone any acts of retaliation against anyone who files  harassment complaints or cooperates in the investigation of same."}),"\n",(0,t.jsx)(n.p,{children:"Also, it is unlawful for  an employer to retaliate against employees who oppose the practices prohibited by the  Fair Employment and Housing Act, or file complaints, or otherwise participate in an  investigation, proceeding, or hearing conducted by the Department of Fair Employment  and Housing. Similarly, the Company prohibits employees from hindering our own  internal investigations and our internal complaint procedure."}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsx)(n.li,{children:"The term \u201charassment\u201d includes but is not limited to unwelcome slurs, jokes, verbal,  graphic or physical conduct relating to an individual\u2019s race, religion, sex, sexual  orientation, age, national origin, or disability."}),"\n",(0,t.jsxs)(n.li,{children:["Sexual harassment consists of unwelcome sexual advances, requests for sexual  favors, or other verbal or physical conduct of a sexual nature where:","\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"Submission to such conduct is an explicit or implicit term or condition of  employment;"}),"\n",(0,t.jsx)(n.li,{children:"Employment decisions are based on an employee\u2019s submission to or rejection of  such conduct; or,"}),"\n",(0,t.jsx)(n.li,{children:"Such conduct interferes with an individual\u2019s work performance or creates an  intimidating, hostile or offensive working environment."}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.li,{children:"The term \u201charassment\u201d may also include conduct of employees, supervisors, vendors  and/or customers who engage in verbally or physically harassing behavior which has  the potential for humiliating or embarrassing an employee of the Company."}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"complaint-procedure",children:"Complaint Procedure"}),"\n",(0,t.jsx)(n.p,{children:"The Company provides its employees with a convenient and reliable method for reporting  incidents of harassment, including sexual harassment. Any employee who feels that they  have been or are being harassed, or discriminated against, is encouraged to immediately  inform the alleged harasser that the behavior is unwelcome."}),"\n",(0,t.jsx)(n.p,{children:"In most instances, the person  is unaware that their conduct is offensive and when so advised can easily and willingly  correct the conduct so that it does not reoccur. If the informal discussion with the alleged  harasser is unsuccessful in remedying the problem or if such an approach is not possible,  the employee should immediately report the complained-of conduct to their immediate  supervisor, manager, owner of the Company, or if necessary, to the Pressure Profile  Systems, Inc. Human Resources Department. The report should include all facts  available to the employee regarding the harassment."}),"\n",(0,t.jsx)(n.h3,{id:"confidentiality",children:"Confidentiality"}),"\n",(0,t.jsx)(n.p,{children:"All reports of harassment will be treated seriously. However, absolute confidentiality is  not promised nor can it be assured. The Company will conduct an investigation of any  complaint which will require limited disclosure of pertinent information to certain parties,  including the alleged harasser."}),"\n",(0,t.jsx)(n.h3,{id:"investigative-procedure",children:"Investigative Procedure"}),"\n",(0,t.jsx)(n.p,{children:"Once a complaint is received, the Company will begin a prompt and thorough  investigation. The investigation may include interviews with all involved employees,  including the alleged harasser, and any employees who are aware of facts or incidents  alleged to have occurred.\nOnce the investigation is completed, a determination will be made regarding the validity  of the harassment allegations. If it is determined that harassment has occurred; prompt,  remedial action will be taken. This may include some or all of the following steps:"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsx)(n.li,{children:"Restore any lost terms, conditions or benefits of employment to the complaining  employee."}),"\n",(0,t.jsx)(n.li,{children:"Discipline the harasser. This discipline can include written disciplinary warnings,  transfer, demotion, suspension, and termination."}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"If the harassment is from a vendor or customer the Company will take appropriate action  to stop the complained-of conduct. The California Department of Fair Employment and Housing and/or the U.S. Equal  Employment Opportunity Commission may also investigate and process complaints of  harassment. Violators are subject to penalties and remedial measures that may include  sanctions, fines, injunctions, reinstatement, back pay, and damages. The address of the  local office of the Department of Fair Employment and Housing and the Commission,  respectively, can be found among the state and federal office listings in the telephone  book."}),"\n",(0,t.jsx)(n.h3,{id:"duties-of-employees-and-supervisors",children:"Duties of Employees and Supervisors"}),"\n",(0,t.jsx)(n.p,{children:"All employees of the Company, both management and non-management, are responsible  for assuring that a workplace free of harassment is maintained. Any employee may file a  harassment complaint regarding incidents experienced personally or incidents observed in  the workplace. The Company strives to maintain a lawful, pleasant work environment  where all employees are able to effectively perform their work without interference of any  type and requests the assistance of all employees in this effort."}),"\n",(0,t.jsx)(n.p,{children:"All Company supervisors and managers are expected to adhere to the Company\u2019s anti harassment policy. Supervisors\u2019 evaluations will include an assessment of the  supervisor\u2019s efforts in following and enforcing this policy."}),"\n",(0,t.jsx)(n.p,{children:"All managers and supervisors are responsible for doing all they can to prevent and  discourage harassment from occurring. If a complaint is raised, supervisors and managers  are to act promptly to notify the Pressure Profile Systems, Inc. Human Resources  Department of the complaint so that Human Resources may proceed with an  investigation. If a supervisor or manager fails to follow this policy they will be  disciplined. Such discipline may include termination."})]})}function p(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>s,x:()=>r});var o=i(6540);const t={},a=o.createContext(t);function s(e){const n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:s(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);